+// SPDX-License-Identifier: MIT
+// Copyright (c) 2025 DeepSeek
+// Device helpers shared by the persistent kernel, its gate sample, the
+// selection and the exact rescan. The TMA loads are DeepGEMM's tma_copy for
+// unswizzled boxes.
+#pragma once
+
+#include <cute/arch/copy_sm90_tma.hpp>
+#include <cutlass/arch/barrier.h>
+#include <deep_gemm/common/ring_pipeline.cuh>
+#include <deep_gemm/ptx/ld_st.cuh>
+#include <deep_gemm/ptx/tcgen05.cuh>
+#include <deep_gemm/ptx/utils.cuh>
+
+#include "constants.h"
+#include <cstdint>
+#include <cuda_fp16.h>
+
+namespace sglang::fused_mqa_topk {
+
+namespace ptx = ::deep_gemm::ptx;
+using ::deep_gemm::RingPipeline;
+using Barrier = cutlass::arch::ClusterTransactionBarrier;
+
+// Mask of all 32 lanes for the warp-synchronous intrinsics.
+inline constexpr uint32_t kFullMask = 0xffffffffu;
+
+// Warp roles of both pipelines (persistent kernel and dense rescan): warps 0-7
+// are the math warps (two warpgroups of kWgRows query rows each), warps 8-11
+// the producer / UMMA / drain warps.
+inline constexpr uint32_t kMathThreads = 256, kMathWgThreads = 128, kMathWarps = kMathThreads / 32;
+inline constexpr uint32_t kWgRows = kBlockRows / 2;
+// Register split: ptxas gives each of the 384 threads 168 registers;
+// setmaxnreg moves them from the producer / UMMA / drain warpgroup to the two
+// math warpgroups.
+inline constexpr uint32_t kMathRegs = 224, kSpecRegs = 168 * 3 - 2 * kMathRegs;
+
+// Named barrier ids (cutlass::arch::NamedBarrier offsets them past the ids it
+// reserves). kBarDenseMath: the dense rescan's math threads; kBarMath /
+// kBarSelect: the math threads; kBarDrain: the math threads and the two drain
+// warps (kDrainThreads); kBarWarpgroup + g: math warpgroup g.
+inline constexpr uint32_t kBarDenseMath = 0, kBarMath = 2, kBarDrain = 4, kBarSelect = 5, kBarWarpgroup = 6;
+inline constexpr uint32_t kDrainThreads = kMathThreads + 2 * 32;
+
+// Barrier of the math threads; the compiler barriers keep shared-memory
+// accesses on their side of it.
+__device__ __forceinline__ void math_sync() {
+  asm volatile("" ::: "memory");
+  cutlass::arch::NamedBarrier(kMathThreads, kBarMath).sync();
+  asm volatile("" ::: "memory");
+}
+
+// Inclusive prefix sum of v over the warp's lanes.
+__device__ __forceinline__ uint32_t warp_inclusive_scan(uint32_t v, uint32_t lane) {
+#pragma unroll
+  for (uint32_t d = 1; d < 32; d *= 2) {
+    const uint32_t u = __shfl_up_sync(kFullMask, v, d);
+    if (lane >= d) v += u;
+  }
+  return v;
+}
+
+// Shared-memory histograms pad one word per 32 (bank conflicts): word w lives
+// at padded_bin(w), a histogram of n words takes padded_bins(n).
+__host__ __device__ constexpr uint32_t padded_bins(uint32_t n) {
+  return n + n / 32;
+}
+__device__ __forceinline__ uint32_t padded_bin(uint32_t w) {
+  return w + w / 32;
+}
+
+// Reads `x` with a volatile load, so the compiler re-reads it from (shared)
+// memory instead of keeping it live in a register.
+template <class T>
+__device__ __forceinline__ T volatile_load(const T& x) {
+  return *reinterpret_cast<const volatile T*>(&x);
+}
+
+// Order-preserving uint32 code of a float (a higher code is a larger value)
+// and its inverse.
+__device__ __forceinline__ uint32_t ordered_code(float x) {
+  const uint32_t u = __float_as_uint(x);
+  return (u & 0x80000000u) ? ~u : (u ^ 0x80000000u);
+}
+__device__ __forceinline__ float ordered_float(uint32_t code) {
+  return __uint_as_float((code & 0x80000000u) ? (code ^ 0x80000000u) : ~code);
+}
+
+// Histogram bin of a score: its fp16 value (rounded down) as an
+// order-preserving 16-bit code, >> kShift; half_bin_floor is the smallest value
+// of bin `b`.
+template <uint32_t kShift>
+__device__ __forceinline__ uint32_t half_bin(float x) {
+  const uint32_t u = __half_as_ushort(__float2half_rd(x));
+  return ((u & 0x8000u) ? ((~u) & 65535u) : (u ^ 0x8000u)) >> kShift;
+}
+template <uint32_t kShift>
+__device__ __forceinline__ float half_bin_floor(uint32_t b) {
+  const uint32_t o = b << kShift, u = (o & 0x8000u) ? (o ^ 0x8000u) : ((~o) & 65535u);
+  return __half2float(__ushort_as_half(u));
+}
+
+// One TMA load of the box at (x, y) (3D: at (x, y, z)) into `smem`, completing
+// on `barrier`.
+template <typename T>
+CUTLASS_DEVICE void tma_load(const void* desc, Barrier* barrier, T* smem, uint32_t x, uint32_t y) {
+  constexpr auto kCacheHint = static_cast<uint64_t>(cute::TMA::CacheHintSm90::EVICT_NORMAL);
+  cute::SM90_TMA_LOAD_2D::copy(desc, reinterpret_cast<uint64_t*>(barrier), kCacheHint, smem, x, y);
+}
+template <typename T>
+CUTLASS_DEVICE void tma_load(const void* desc, Barrier* barrier, T* smem, uint32_t x, uint32_t y, uint32_t z) {
+  constexpr auto kCacheHint = static_cast<uint64_t>(cute::TMA::CacheHintSm90::EVICT_NORMAL);
+  cute::SM90_TMA_LOAD_3D::copy(desc, reinterpret_cast<uint64_t*>(barrier), kCacheHint, smem, x, y, z);
+}
+
+}  // namespace sglang::fused_mqa_topk

@@ -0,0 +1,353 @@
+// SPDX-License-Identifier: MIT
+// Copyright (c) 2025 DeepSeek
+// Dense FP8 MQA scoring of one block over its whole KV range, for the exact
+// rescan: DeepGEMM's SM100 MQA-logits pipeline (contiguous KV, 32 heads,
+// D = 128; its shared-storage layout with fp32 per-key scales and fp32
+// weights and its grid-stride scheduler, as of the release before its SM100
+// kernels went MX-only), with the logits store replaced by a per-score policy.
+//
+// Roles (384 threads): warps 0-7 reduce the 32 heads (4 rows per warpgroup),
+// warp 8 loads Q and the weights, warp 9 the KV tiles and their scales, warp 10
+// issues the UMMAs, warp 11 is idle.
+//
+// Policy interface (all called by the math warps):
+//   kWeightScale, kScoreScale: score = (sum_h kWeightScale * w_h * (s_h + |s_h|))
+//     * kScoreScale * scale_kv
+//   begin_block(sched, q_block, query_base): after the block's Q / weights landed
+//   begin_split(split, query_base): before the split's scores
+//   score(i, kv_offset, kv_lane, split, score): row query_base + i of the warpgroup
+//   end_split(split, num_splits, kv_base): after the split's scores
+//   end_block(sched, q_block): before the block's Q stage is released
+#pragma once
+
+#include <cute/arch/cluster_sm90.hpp>
+#include <cute/arch/copy_sm90_desc.hpp>
+#include <cutlass/arch/reg_reconfig.h>
+#include <deep_gemm/common/cute_tie.cuh>
+#include <deep_gemm/common/utils.cuh>
+#include <deep_gemm/mma/sm100.cuh>
+
+#include "common.cuh"
+#include <cstdint>
+
+namespace sglang::fused_mqa_topk::dense {
+
+inline constexpr uint32_t BLOCK_Q = kBlockRows, SPLIT_KV = kTileKeys;
+inline constexpr uint32_t kNumKVStages = 2, kNumTmemStages = 2;
+inline constexpr uint32_t UMMA_M = 128, UMMA_N = BLOCK_Q * kNumHeads, UMMA_K = 32;
+
+// DeepGEMM's MQALogitsSharedStorage for FP8 Q / K with one Q stage.
+struct SharedStorage {
+  // One 8-row Q / K swizzle tile (kHeadDim bytes per FP8 token).
+  static constexpr uint32_t kSwizzleAlignment = 8 * kHeadDim;
+  // TMA destinations in shared memory must be 128-byte aligned.
+  static constexpr uint32_t kTmaAlignment = 128;
+  static constexpr uint32_t kNumWeightElementsPerStage = BLOCK_Q * kNumHeads;
+  static_assert(kNumHeads * sizeof(float) % 16 == 0 && BLOCK_Q * kNumHeads * sizeof(float) % kTmaAlignment == 0);
+
+  alignas(kSwizzleAlignment) cutlass::float_e4m3_t smem_q[1][UMMA_N * kHeadDim];
+  alignas(kSwizzleAlignment) cutlass::float_e4m3_t smem_kv[kNumKVStages][SPLIT_KV * kHeadDim];
+  // DeepGEMM's per-stage Q scale (unused by FP8 Q; kept so the layout matches).
+  alignas(kTmaAlignment) float smem_sf_q[1][1];
+  alignas(kTmaAlignment) float smem_sf_kv[kNumKVStages][SPLIT_KV];
+  alignas(kTmaAlignment) float smem_weights[1][kNumWeightElementsPerStage];
+  // Barriers require 8-byte alignment, already guaranteed by the preceding
+  // TMA-aligned arrays.
+  Barrier full_q_barriers[1];
+  Barrier empty_q_barriers[1];
+  Barrier full_kv_barriers[kNumKVStages];
+  Barrier empty_kv_barriers[kNumKVStages];
+  Barrier full_tmem_barriers[kNumTmemStages];
+  Barrier empty_tmem_barriers[kNumTmemStages];
+  uint32_t tmem_ptr_in_smem;
+};
+
+// DeepGEMM's grid-stride contiguous-KV scheduler: SM `s` owns Q blocks `s`,
+// `s + kNumSMs`, ..., each visiting the KV range [min k_start, max k_end) of
+// its rows. Rows past the end are clamped to the last valid row.
+struct Scheduler {
+  static constexpr uint32_t kNumSMs = 4096;
+
+  uint32_t current_q_block_idx;
+  uint32_t num_q_blocks;
+  uint32_t num_q_tokens;
+  uint32_t num_kv_tokens;
+  const uint32_t* cu_seq_len_k_start;
+  const uint32_t* cu_seq_len_k_end;
+
+  CUTLASS_DEVICE Scheduler(
+      const uint32_t& sm_idx,
+      const uint32_t& num_q_tokens,
+      const uint32_t& num_kv_tokens,
+      const uint32_t* cu_seq_len_k_start,
+      const uint32_t* cu_seq_len_k_end)
+      : current_q_block_idx(sm_idx),
+        num_q_blocks(deep_gemm::math::ceil_div(num_q_tokens, BLOCK_Q)),
+        num_q_tokens(num_q_tokens),
+        num_kv_tokens(num_kv_tokens),
+        cu_seq_len_k_start(cu_seq_len_k_start),
+        cu_seq_len_k_end(cu_seq_len_k_end) {}
+
+  CUTLASS_DEVICE bool next_q_block(uint32_t& q_block_idx, uint32_t& kv_token_base, uint32_t& num_kv_splits) {
+    if (current_q_block_idx >= num_q_blocks) return false;
+    q_block_idx = current_q_block_idx;
+    current_q_block_idx += kNumSMs;
+    uint32_t start = cute::numeric_limits<uint32_t>::max();
+    uint32_t end = cute::numeric_limits<uint32_t>::min();
+#pragma unroll 8
+    for (uint32_t token_idx = 0; token_idx < BLOCK_Q; ++token_idx) {
+      const auto row_idx = cute::min(q_block_idx * BLOCK_Q + token_idx, num_q_tokens - 1);
+      start = cute::min(start, cute::min(cu_seq_len_k_start[row_idx], num_kv_tokens));
+      end = cute::max(end, cute::min(cu_seq_len_k_end[row_idx], num_kv_tokens));
+    }
+    kv_token_base = start / 4 * 4;
+    num_kv_splits = deep_gemm::math::ceil_div(end - kv_token_base, SPLIT_KV);
+    return true;
+  }
+
+  CUTLASS_DEVICE uint32_t get_q_tma_token_base(const uint32_t& q_block_idx) const {
+    return q_block_idx * BLOCK_Q;
+  }
+
+  CUTLASS_DEVICE static uint32_t get_kv_tma_offset(const uint32_t& kv_token_base, const uint32_t& kv_split_idx) {
+    return kv_token_base + kv_split_idx * SPLIT_KV;
+  }
+
+  CUTLASS_DEVICE static uint32_t get_logits_row(const uint32_t& q_block_idx, const uint32_t& token_idx) {
+    return q_block_idx * BLOCK_Q + token_idx;
+  }
+
+  CUTLASS_DEVICE static uint32_t
+  get_logits_col(const uint32_t& kv_token_base, const uint32_t& kv_split_idx, const uint32_t& math_thread_idx) {
+    return kv_token_base + kv_split_idx * SPLIT_KV + math_thread_idx;
+  }
+};
