+// Scheduler of the single block `q_block` (a deferred block of the persistent
+// kernel): its rows end with the block, so the grid stride never yields a
+// second block (over all `rows` it would also score q_block + kNumSMs).
+CUTLASS_DEVICE Scheduler
+block_scheduler(uint32_t q_block, uint32_t rows, uint32_t keys, const uint32_t* starts, const uint32_t* ends) {
+  return Scheduler(q_block, min(rows, (q_block + 1) * BLOCK_Q), keys, starts, ends);
+}
