+      for (uint32_t kv_split_idx = 0; kv_split_idx < num_kv_splits; ++kv_split_idx) {
+        policy.begin_split(kv_split_idx, query_base);
+        CUTE_TIE_DECL(kv_pipeline.advance(), kv_stage_idx, kv_phase);
