+                  pair + r, kv_offset, kv_lane, kv_split_idx, (sum.x + sum.y) * (Policy::kScoreScale * scale_kv));
+            }
+          }
+        }
+        policy.end_split(kv_split_idx, num_kv_splits, kv_base);
