+      smem.empty_q_barriers[q_stage_idx].arrive();
+    }
+    cutlass::arch::NamedBarrier(kMathThreads, kBarDenseMath).sync();
+    if (warp_idx == 0) cute::TMEM::Allocator1Sm().free(0, kNumTmemCols);
+  }
