+                   sr = __shfl_sync(kFullMask, rstart, src + 3), d0 = __shfl_sync(kFullMask, rdelta, src),
+                   d1 = __shfl_sync(kFullMask, rdelta, src + 1), d2 = __shfl_sync(kFullMask, rdelta, src + 2),
+                   d3 = __shfl_sync(kFullMask, rdelta, src + 3);
