+            "@q st.global.cg.u32 [%3], %4;\n\t}" ::"r"(ok[u]),
+            "l"(vrow + uint64_t(hc[u]) * 2u),
+            "h"(static_cast<uint16_t>(code >> 8)),
+            "l"(irow + uint64_t(hc[u]) * 4u),
+            "r"(idx)
